"""Anatomy of the provided code graphs vs. the source they were built from (per unique commit)."""
import json, os, sys, collections
import numpy as np
sys.path.insert(0, os.environ.get('GL_CODE', '/kaggle/working'))
import graphloc as G

OUT = os.environ.get('GL_OUT', '/kaggle/working/results')
tasks = G.load_tasks()
seen, per_commit = set(), []
for t in tasks:
    if t['base_commit'] in seen:
        continue
    seen.add(t['base_commit']); per_commit.append(t)
rows = []
for t in per_commit:
    files = G.load_snapshot_py(t['instance_id'])
    gp_path = G.resource_path(t, tasks, 'graphs')
    raw = json.load(open(gp_path))
    ids = [n['id'] for n in raw['nodes']]
    idset = set(ids)
    g0 = G.Graph(ids, [n.get('text') or '' for n in raw['nodes']], [(e['source'], e['target']) for e in raw['edges']])
    E = [(e['source'], e['target']) for e in raw['edges']]
    Eset = set(E)
    contain_like = sum(1 for s, d in E if d.startswith(s + '.') or s.startswith(d + '.'))
    recip = sum(1 for s, d in E if (d, s) in Eset)
    selfl = sum(1 for s, d in E if s == d)
    dangling = sum(1 for s, d in E if s not in idset or d not in idset)
    fd = {}
    for p, src in files.items():
        r = G.extract_defs(src)
        fd[p] = r[0] or []
    mm = G.assign_modules(fd, idset)
    c = collections.Counter()
    exact_ids = set()
    flat_hits = collections.Counter()
    for p, defs in fd.items():
        area = 'test' if G.is_test_path(p) else ('docs' if p.startswith('docs') else 'lib')
        mod = mm[p]
        qual_kind = {d['qual']: d for d in defs}
        for d in defs:
            full = mod + '.' + d['qual']
            if not d['nested']:
                exact_ids.add(full)
                key = f"{area}_{d['kind']}"
                c[key + '_n'] += 1
                c[key + '_in'] += full in idset
            else:
                parts = d['qual'].split('.')
                # candidate flattenings
                outer_cls = []
                for k in range(1, len(parts)):
                    q = '.'.join(parts[:k])
                    if qual_kind.get(q, {}).get('kind') == 'class':
                        outer_cls = parts[:k]
                    else:
                        break
                cand_a = mod + '.' + d['name']
                cand_b = mod + '.' + '.'.join(outer_cls + [d['name']]) if outer_cls else None
                c[f'{area}_nested_n'] += 1
                c[f'{area}_nested_exact'] += full in idset
                c[f'{area}_nested_flat_mod'] += cand_a in idset
                c[f'{area}_nested_flat_cls'] += bool(cand_b and cand_b in idset and cand_b != full)
                if full not in idset:
                    flat_hits[cand_b if (cand_b and cand_b in idset) else cand_a] += 1
    nonexact = [i for i in ids if i not in exact_ids]
    collisions = sum(1 for k, v in flat_hits.items() if k in idset and (v > 1 or k in exact_ids))
    module_nodes = sum(1 for i in ids if i in set(mm.values()))
    row = {'id': t['instance_id'], 'repo': t['repo'], 'nodes': len(ids), 'raw_edges': len(E),
           'undirected_edges': g0.n_edges, 'isolated': int((g0.deg == 0).sum()),
           'edge_types': dict(collections.Counter(e.get('type') for e in raw['edges'])),
           'contain_like_edges': contain_like, 'reciprocal_edges': recip, 'self_loops': selfl, 'dangling': dangling,
           'nonexact_ids': len(nonexact), 'nonexact_sample': nonexact[:8], 'flat_collisions': collisions,
           'module_nodes': module_nodes, 'counts': dict(c),
           'mean_deg': float(g0.deg.mean()), 'max_deg': int(g0.deg.max())}
    rows.append(row)
    print(row['id'], row['nodes'], row['undirected_edges'], row['isolated'], dict(c).get('lib_async_n'), dict(c).get('lib_async_in'), flush=True)
with open(f'{OUT}/anatomy.jsonl', 'w') as f:
    for r in rows:
        f.write(json.dumps(r) + '\n')
