            sa = X[a] @ X.T; sa[a] = -9
            seen.update(ids[j] for j in np.argpartition(-sa, 10)[:10])
        res[k]['tool_similar_hit'] += bool(seen & gold)
out = {'n_tasks_with_anchors': n_with,
       'retrieval': {k: {m: round(v / n_with, 3) for m, v in c.items()} for k, c in res.items()},
