"""Aggregate main.jsonl rows into the paper's tables (prints compact text + writes summary.json)."""
import json, glob, os, sys, collections
import numpy as np

OUT = os.environ.get('GL_OUT', '/kaggle/working/results')
PAT = os.environ.get('PAT', 'main_*.jsonl')
rows = []
for p in sorted(glob.glob(f'{OUT}/{PAT}')):
    rows += [json.loads(l) for l in open(p)]
rows = [r for r in rows if 'error' not in r]
rows.sort(key=lambda r: r['id'])
rng = np.random.default_rng(0)
S = {'n_tasks': len(rows)}


def hit(rank, k):
    return rank is not None and rank <= k


def mrr(rank):
    return 0.0 if rank is None else 1.0 / rank


def table(sub, key, methods, ks=(1, 5, 10)):
    out = {}
    for m in methods:
        rk = [r[key].get(m) for r in sub]
        out[m] = {f'H@{k}': round(float(np.mean([hit(x, k) for x in rk])), 3) for k in ks}
        out[m]['MRR'] = round(float(np.mean([mrr(x) for x in rk])), 3)
    return out


def paired_boot(sub, key, a, b, k, B=2000):
    xa = np.array([hit(r[key].get(a), k) for r in sub], float)
    xb = np.array([hit(r[key].get(b), k) for r in sub], float)
    d = xb - xa
    bs = [d[rng.integers(0, len(d), len(d))].mean() for _ in range(B)]
    only_a, only_b = int(((xa == 1) & (xb == 0)).sum()), int(((xa == 0) & (xb == 1)).sum())
    return {'delta': round(float(d.mean()), 3), 'ci95': [round(float(np.percentile(bs, 2.5)), 3), round(float(np.percentile(bs, 97.5)), 3)],
            'only_a': only_a, 'only_b': only_b}


# ------------------------------------------------ labels & coverage
cat = collections.Counter(); cat_in0 = collections.Counter(); cat_inp = collections.Counter()
tf = [r for r in rows if r['gold_symbols']]
for r in rows:
    for s, v in r['gold_symbols'].items():
        cat[v['cat']] += 1; cat_in0[v['cat']] += v['in_g0']; cat_inp[v['cat']] += v['in_gp']
S['labels'] = {
    'tasks_with_gold_file': sum(bool(r['gold_files']) for r in rows),
    'tasks_new_file_only': sum((not r['gold_files']) and bool(r['new_files']) for r in rows),
    'tasks_with_symbol_gold': len(tf),
    'gold_files_per_task_mean': round(float(np.mean([len(r['gold_files']) for r in rows if r['gold_files']])), 2),
    'gold_symbols_per_task_mean': round(float(np.mean([len(r['gold_symbols']) for r in tf])), 2),
    'symbols_by_cat': dict(cat), 'in_g0_by_cat': dict(cat_in0), 'in_gp_by_cat': dict(cat_inp),
    'tasks_any_gold_in_g0': sum(any(v['in_g0'] for v in r['gold_symbols'].values()) for r in tf),
    'tasks_all_gold_in_g0': sum(all(v['in_g0'] for v in r['gold_symbols'].values()) for r in tf),
    'tasks_any_async_gold': sum(any(v['cat'] == 'async' for v in r['gold_symbols'].values()) for r in tf),
    'tasks_any_gold_in_gp': sum(any(v['in_gp'] for v in r['gold_symbols'].values()) for r in tf),
    'tasks_with_new_symbols': sum(bool(r['new_symbols']) for r in rows),
    'tasks_nonpy_edits': sum(bool(r['nonpy_files']) for r in rows),
}
by_repo = collections.defaultdict(list)
for r in tf:
    by_repo[r['repo']].append(r)
S['labels']['by_repo'] = {k: {'n': len(v), 'any_in_g0': sum(any(x['in_g0'] for x in r['gold_symbols'].values()) for r in v),
                               'any_async': sum(any(x['cat'] == 'async' for x in r['gold_symbols'].values()) for r in v)} for k, v in by_repo.items()}
# ------------------------------------------------ graph sizes
S['graph'] = {'g0_nodes_mean': round(float(np.mean([r['n_nodes_g0'] for r in rows])), 1),
              'g0_edges_mean': round(float(np.mean([r['n_edges_g0'] for r in rows])), 1),
              'gp_nodes_mean': round(float(np.mean([r['n_nodes_gp'] for r in rows])), 1),
              'gp_edges_mean': round(float(np.mean([r['n_edges_gp'] for r in rows])), 1),
              'cand_g0_mean': round(float(np.mean([r['n_cand_g0'] for r in rows])), 1),
              'cand_gp_mean': round(float(np.mean([r['n_cand_gp'] for r in rows])), 1)}
# ------------------------------------------------ anchors & tool simulation
S['anchors'] = {
    'tasks_with_mentions': sum(r['n_mentions'] > 0 for r in rows),
    'tasks_with_any_resolution': sum(any(int(k) >= 1 for k in r['anchor_tiers_g0']) for r in rows),
    'tasks_with_seeds_g0': sum(bool(r['seeds_g0']) for r in rows),
    'tasks_with_seeds_gp': sum(bool(r['seeds_gp']) for r in rows),
    'tier_counts': dict(sum((collections.Counter(r['anchor_tiers_g0']) for r in rows), collections.Counter())),
}
S['tool_sim'] = {k: sum(r['tool_sim'][k] for r in tf) for k in ('anchor_only', 'neighbors', 'similar', 'both')}
S['tool_sim']['n_tasks'] = len(tf)
S['tool_sim']['mean_calls'] = round(float(np.mean([r['tool_sim']['n_calls'] for r in tf])), 1)
hops0 = collections.Counter(r['hops_g0'] for r in tf)
