                exact_ids.add(full)
                key = f"{area}_{d['kind']}"
                c[key + '_n'] += 1
                c[key + '_in'] += full in idset
            else:
                parts = d['qual'].split('.')
                # candidate flattenings
                outer_cls = []
                for k in range(1, len(parts)):
                    q = '.'.join(parts[:k])
                    if qual_kind.get(q, {}).get('kind') == 'class':
                        outer_cls = parts[:k]
                    else:
