                cand_a = mod + '.' + d['name']
                cand_b = mod + '.' + '.'.join(outer_cls + [d['name']]) if outer_cls else None
                c[f'{area}_nested_n'] += 1
                c[f'{area}_nested_exact'] += full in idset
                c[f'{area}_nested_flat_mod'] += cand_a in idset
                c[f'{area}_nested_flat_cls'] += bool(cand_b and cand_b in idset and cand_b != full)
                if full not in idset:
                    flat_hits[cand_b if (cand_b and cand_b in idset) else cand_a] += 1
    nonexact = [i for i in ids if i not in exact_ids]
    collisions = sum(1 for k, v in flat_hits.items() if k in idset and (v > 1 or k in exact_ids))
