           'module_nodes': module_nodes, 'counts': dict(c),
           'mean_deg': float(g0.deg.mean()), 'max_deg': int(g0.deg.max())}
    rows.append(row)
    print(row['id'], row['nodes'], row['undirected_edges'], row['isolated'], dict(c).get('lib_async_n'), dict(c).get('lib_async_in'), flush=True)
with open(f'{OUT}/anatomy.jsonl', 'w') as f:
