"""Follow-up probe: are the provided embeddings a function of (id, text) only, or do they depend on graph structure?"""
import json, os, sys, collections
import numpy as np
sys.path.insert(0, os.environ.get('GL_CODE', '/kaggle/working'))
import graphloc as G

OUT = os.environ.get('GL_OUT', '/kaggle/working/results')
tasks = G.load_tasks()
seen, per_commit = set(), []
for t in sorted(tasks, key=lambda t: t['created_at']):
    if t['base_commit'] not in seen:
        seen.add(t['base_commit']); per_commit.append(t)
prev = {}
acc = collections.defaultdict(list)
for t in per_commit:
    raw = json.load(open(G.resource_path(t, tasks, 'graphs')))
    z = np.load(G.resource_path(t, tasks, 'embeddings'))
    text = {n['id']: n.get('text') or '' for n in raw['nodes']}
    nb = collections.defaultdict(set)
    for e in raw['edges']:
        nb[e['source']].add(e['target']); nb[e['target']].add(e['source'])
    vec = {k: z[k] / max(np.linalg.norm(z[k]), 1e-9) for k in text}
    if t['repo'] in prev:
        ptext, pnb, pvec = prev[t['repo']]
        for k in text:
            if k in ptext:
                c = float(vec[k] @ pvec[k])
                same_text = text[k] == ptext[k]
                same_nb = nb[k] == pnb[k]
                acc[f'text{int(same_text)}_nb{int(same_nb)}'].append(c)
    prev[t['repo']] = (text, nb, vec)
    # same short name, different node: how similar?
    by_name = collections.defaultdict(list)
    for k in text:
        by_name[k.rsplit('.', 1)[-1]].append(k)
    rng = np.random.default_rng(len(text))
    keys = list(text)
    for name, ks in by_name.items():
        if len(ks) > 1 and not name.startswith('test'):
            acc['same_name'].append(float(vec[ks[0]] @ vec[ks[1]]))
            r = keys[rng.integers(len(keys))]
            acc['random_pair'].append(float(vec[ks[0]] @ vec[r]))
    # class vs its own methods
    for k in text:
        parent = k.rsplit('.', 1)[0]
        if parent in text and text[parent].startswith('class '):
            acc['class_method'].append(float(vec[k] @ vec[parent]))
out = {k: {'n': len(v), 'mean': round(float(np.mean(v)), 4), 'frac_identical': round(float(np.mean(np.array(v) > 0.9999)), 4)} for k, v in acc.items()}
json.dump(out, open(f'{OUT}/emb_probe2.json', 'w'), indent=1)
print(json.dumps(out))
