"""Does fixing embedding anisotropy (centering / removing top PCs) make search_similar_code a better localizer?"""
import glob, json, os, sys, collections
import numpy as np
sys.path.insert(0, os.environ.get('GL_CODE', '/kaggle/working'))
import graphloc as G

OUT = os.environ.get('GL_OUT', '/kaggle/working/results')
tasks = {t['instance_id']: t for t in G.load_tasks()}
tl = list(tasks.values())
rows = []
for p in glob.glob(f'{OUT}/main_*.jsonl'):
    rows += [json.loads(l) for l in open(p)]
rows = [r for r in rows if 'error' not in r and r['gold_symbols']]


def transforms(E):
    En = E / np.maximum(np.linalg.norm(E, axis=1, keepdims=True), 1e-9)
    mu = E.mean(0)
    C = E - mu
    Cn = C / np.maximum(np.linalg.norm(C, axis=1, keepdims=True), 1e-9)
    U, S, Vt = np.linalg.svd(C - C.mean(0), full_matrices=False)
    A = C - (C @ Vt[:3].T) @ Vt[:3]
    An = A / np.maximum(np.linalg.norm(A, axis=1, keepdims=True), 1e-9)
    return {'raw': En, 'centered': Cn, 'abtt3': An}


def kocc_skew(X, k=10, m=400, rng=np.random.default_rng(0)):
    n = len(X)
    idx = rng.choice(n, size=min(m, n), replace=False)
    S = X[idx] @ X.T
    S[np.arange(len(idx)), idx] = -9
    occ = np.zeros(n)
    for r in range(len(idx)):
        occ[np.argpartition(-S[r], k)[:k]] += 1
    return float(((occ - occ.mean()) ** 3).mean() / (occ.std() ** 3 + 1e-12)), float(np.mean(np.sort(occ)[::-1][:max(1, n // 100)]) / max(occ.mean(), 1e-9))


res = collections.defaultdict(lambda: collections.Counter())
hub = collections.defaultdict(list)
n_with = 0
for r in rows:
    t = tasks[r['id']]
    seeds = r['seeds_g0']
    raw = json.load(open(G.resource_path(t, tl, 'graphs')))
    ids = [n['id'] for n in raw['nodes']]
    idx = {n: i for i, n in enumerate(ids)}
    z = np.load(G.resource_path(t, tl, 'embeddings'))
    E = np.stack([z[n] for n in ids]).astype(np.float64)
    V = transforms(E)
    if len(hub['raw']) < 40:
        for k, X in V.items():
            hub[k].append(kocc_skew(X))
    gold = set(r['gold_symbols'])
    cand = np.array([i for i, n in enumerate(ids) if not G.is_test_id(n)])
    if not seeds:
        continue
    n_with += 1
    si = [idx[s] for s in seeds if s in idx]
    for k, X in V.items():
        s = (X[si] @ X.T).max(0)
        s[si] += 1.0
        order = cand[np.argsort(-s[cand], kind='stable')]
        rk = G.first_hit_rank([ids[i] for i in order], gold)
        for kk in (1, 5, 10):
            res[k][f'H@{kk}'] += bool(rk and rk <= kk)
        # tool-faithful: union of top-10 neighbours of each anchor (anchor excluded)
        seen = set()
        for a in si[:10]:
