        res[k]['tool_similar_hit'] += bool(seen & gold)
out = {'n_tasks_with_anchors': n_with,
       'retrieval': {k: {m: round(v / n_with, 3) for m, v in c.items()} for k, c in res.items()},
       'hubness': {k: {'kocc_skew': round(float(np.mean([a for a, _ in v])), 3), 'top1pct_occ_ratio': round(float(np.mean([b for _, b in v])), 2)} for k, v in hub.items()}}
json.dump(out, open(f'{OUT}/emb_probe3.json', 'w'), indent=1)
print(json.dumps(out))
