"""What do nodes that receive (near-)identical embedding vectors have in common?"""
import json, os, sys, collections
import numpy as np
sys.path.insert(0, os.environ.get('GL_CODE', '/kaggle/working'))
import graphloc as G

OUT = os.environ.get('GL_OUT', '/kaggle/working/results')
tasks = G.load_tasks()
seen, per_commit = set(), []
for t in tasks:
    if t['base_commit'] not in seen:
        seen.add(t['base_commit']); per_commit.append(t)
C = collections.Counter()
examples = []
for t in per_commit:
    raw = json.load(open(G.resource_path(t, tasks, 'graphs')))
    z = np.load(G.resource_path(t, tasks, 'embeddings'))
    ids = [n['id'] for n in raw['nodes']]
    text = {n['id']: n.get('text') or '' for n in raw['nodes']}
    E = np.stack([z[i] for i in ids]).astype(np.float64)
    En = E / np.maximum(np.linalg.norm(E, axis=1, keepdims=True), 1e-9)
    key = collections.defaultdict(list)
    for i, v in enumerate(np.round(En, 4)):
        key[v.tobytes()].append(i)
    groups = [g for g in key.values() if len(g) > 1]
    C['nodes'] += len(ids)
    C['nodes_in_identical_groups'] += sum(len(g) for g in groups)
    C['groups'] += len(groups)
    for g in groups:
        a, b = ids[g[0]], ids[g[1]]
        C['pairs'] += 1
        C['same_short_name'] += a.rsplit('.', 1)[-1] == b.rsplit('.', 1)[-1]
        C['same_text'] += text[a] == text[b]
        C['same_module'] += a.rsplit('.', 1)[0] == b.rsplit('.', 1)[0]
        C['same_name_diff_text'] += (a.rsplit('.', 1)[-1] == b.rsplit('.', 1)[-1]) and text[a] != text[b]
        if len(examples) < 12 and text[a] != text[b]:
            examples.append([a, b, text[a][:80], text[b][:80]])
    # among same-short-name pairs: identical vs text equality
    by = collections.defaultdict(list)
    for i, n in enumerate(ids):
        by[n.rsplit('.', 1)[-1]].append(i)
    for nm, g in by.items():
        if len(g) > 1:
            i, j = g[0], g[1]
            ident = float(En[i] @ En[j]) > 0.9999
            st = text[ids[i]] == text[ids[j]]
            C[f'samename_textsame{int(st)}_n'] += 1
            C[f'samename_textsame{int(st)}_ident'] += ident
out = {'counts': dict(C), 'examples': examples}
json.dump(out, open(f'{OUT}/emb_probe4.json', 'w'), indent=1)
